local SpiceRackMaker = {}
local PRODUCTS = {
    iron_spice_rack = { name = "Železno stojalo za začimbe", ironCost = 2, woodCost = 3, leatherCost = 1, time = 5, cost = 160, prestige = 3, happiness = 2, description = "Železno stojalo za začimbe v kuhinji." },
    bronze_spice_rack = { name = "Bronasto stojalo za začimbe", bronzeCost = 2, ironCost = 1, woodCost = 3, leatherCost = 1, time = 7, cost = 390, prestige = 5, happiness = 3, description = "Bronasto stojalo za začimbe v pekarni." },
    silver_spice_rack = { name = "Srebrno stojalo za začimbe", silverCost = 2, bronzeCost = 1, ironCost = 1, woodCost = 3, leatherCost = 1, time = 11, cost = 950, prestige = 10, happiness = 4, description = "Srebrno stojalo za plemiške kuharje." },
    gilded_spice_rack = { name = "Pozlačeno stojalo za začimbe", goldCost = 1, silverCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 15, cost = 2050, prestige = 19, happiness = 5, description = "Pozlačeno stojalo za dvorne kuharje." },
    jewel_set_spice_rack = { name = "Draguljasto stojalo za začimbe", goldCost = 2, silverCost = 2, jewelCost = 1, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 19, cost = 4400, prestige = 35, happiness = 7, description = "Draguljasto stojalo za kraljeve kuharje." },
    royal_sovereign_spice_rack = { name = "Kraljevski suvereno stojalo za začimbe", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 4, leatherCost = 1, time = 26, cost = 9500, prestige = 67, happiness = 13, description = "Suvereno stojalo z biseri za krono." },
}
local BUILDINGS = {
    spicerack_workshop = { name = "Začimbična delavnica", cost = { gold = 325, wood = 185, stone = 130, iron = 7 }, upkeep = 6, qualityBonus = 5 },
    spicerack_house = { name = "Začimbična hiša", cost = { gold = 1180, wood = 365, stone = 265, silver = 7, iron = 7 }, upkeep = 25, qualityBonus = 18 },
    master_spicerack_atelier = { name = "Mojstrski začimbični atelje", cost = { gold = 2980, wood = 425, stone = 515, silver = 35, gold = 7 }, upkeep = 70, qualityBonus = 30 },
    sovereign_spicerack_palace = { name = "Suverena začimbična palača", cost = { gold = 12900, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
SpiceRackMaker.ironStock = 12; SpiceRackMaker.bronzeStock = 10; SpiceRackMaker.woodStock = 18; SpiceRackMaker.leatherStock = 10; SpiceRackMaker.silverStock = 8; SpiceRackMaker.goldStock = 6; SpiceRackMaker.jewelStock = 4; SpiceRackMaker.pearlStock = 4
SpiceRackMaker.productStock = {}; SpiceRackMaker.buildings = {}; SpiceRackMaker.maker = nil; SpiceRackMaker.activeMaking = {}; SpiceRackMaker.totalProducts = 0; SpiceRackMaker.dayTimer = 0
function SpiceRackMaker.init() SpiceRackMaker.ironStock=12; SpiceRackMaker.bronzeStock=10; SpiceRackMaker.woodStock=18; SpiceRackMaker.leatherStock=10; SpiceRackMaker.silverStock=8; SpiceRackMaker.goldStock=6; SpiceRackMaker.jewelStock=4; SpiceRackMaker.pearlStock=4; SpiceRackMaker.productStock={}; SpiceRackMaker.buildings={}; SpiceRackMaker.maker=nil; SpiceRackMaker.activeMaking={}; SpiceRackMaker.totalProducts=0; SpiceRackMaker.dayTimer=0; print("[SpiceRackMaker] Royal Spice Rack Maker System initialized (6 products, 4 buildings)") end
function SpiceRackMaker.hireMaker(n,s) s=s or math.random(55,90); local c=565+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; SpiceRackMaker.maker={name=n or ("Začimbar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Začimbar najet: %s (spretnost: %d)",SpiceRackMaker.maker.name,s),"success") end; return true end
function SpiceRackMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function SpiceRackMaker.build(id) local ok,e=SpiceRackMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(SpiceRackMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function SpiceRackMaker.getQualityBonus() local b=0; for _,bd in ipairs(SpiceRackMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function SpiceRackMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and SpiceRackMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and SpiceRackMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and SpiceRackMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and SpiceRackMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and SpiceRackMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and SpiceRackMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and SpiceRackMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and SpiceRackMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #SpiceRackMaker.buildings==0 then return false,"Potrebna začimbična delavnica" end; if not SpiceRackMaker.maker then return false,"Potreben začimbar" end; return true end
function SpiceRackMaker.make(pt,qty) qty=qty or 1; local ok,e=SpiceRackMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then SpiceRackMaker.ironStock=SpiceRackMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then SpiceRackMaker.bronzeStock=SpiceRackMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then SpiceRackMaker.woodStock=SpiceRackMaker.woodStock-d.woodCost*qty end; if d.leatherCost then SpiceRackMaker.leatherStock=SpiceRackMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then SpiceRackMaker.silverStock=SpiceRackMaker.silverStock-d.silverCost*qty end; if d.goldCost then SpiceRackMaker.goldStock=SpiceRackMaker.goldStock-d.goldCost*qty end; if d.jewelCost then SpiceRackMaker.jewelStock=SpiceRackMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then SpiceRackMaker.pearlStock=SpiceRackMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if SpiceRackMaker.maker then t=math.max(1,t-math.floor(SpiceRackMaker.maker.skill/13)) end; table.insert(SpiceRackMaker.activeMaking,{id="spicerack_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function SpiceRackMaker.completeMaking(m) local q=1.0+(SpiceRackMaker.getQualityBonus()/100); if SpiceRackMaker.maker then q=q+(SpiceRackMaker.maker.skill/140) end; q=math.min(2.5,q); SpiceRackMaker.productStock[m.productType]=(SpiceRackMaker.productStock[m.productType] or 0)+m.quantity; SpiceRackMaker.totalProducts=SpiceRackMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if SpiceRackMaker.maker then SpiceRackMaker.maker.itemsMade=SpiceRackMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then SpiceRackMaker.maker.skill=math.min(100,SpiceRackMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Stojalo izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"spicerack.completed",{productName=m.productName,prestige=m.prestige,happiness:m.happiness}) end end
function SpiceRackMaker.update(dt) if not _G.state then return end; SpiceRackMaker.dayTimer=SpiceRackMaker.dayTimer+dt; if SpiceRackMaker.dayTimer>=30 then SpiceRackMaker.dayTimer=0; for i=#SpiceRackMaker.activeMaking,1,-1 do local m=SpiceRackMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then SpiceRackMaker.completeMaking(m); table.remove(SpiceRackMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(SpiceRackMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if SpiceRackMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function SpiceRackMaker.getStats() return {ironStock=SpiceRackMaker.ironStock,bronzeStock=SpiceRackMaker.bronzeStock,woodStock=SpiceRackMaker.woodStock,leatherStock=SpiceRackMaker.leatherStock,silverStock=SpiceRackMaker.silverStock,goldStock=SpiceRackMaker.goldStock,jewelStock=SpiceRackMaker.jewelStock,pearlStock=SpiceRackMaker.pearlStock,productStock=SpiceRackMaker.productStock,numBuildings=#SpiceRackMaker.buildings,hasMaker=SpiceRackMaker.maker~=nil,makerName=SpiceRackMaker.maker and SpiceRackMaker.maker.name or "—",makerSkill=SpiceRackMaker.maker and SpiceRackMaker.maker.skill or 0,activeMaking=#SpiceRackMaker.activeMaking,totalProducts=SpiceRackMaker.totalProducts} end
return SpiceRackMaker
